@Test void arrayListIsSizedAndOrdered() {
    Spliterator<String> split = List.of("A", "B").spliterator();
    assertThat(split.hasCharacteristics(Spliterator.SIZED)).isTrue();
    assertThat(split.hasCharacteristics(Spliterator.ORDERED)).isTrue();
}

@Test void hashSetIsDistinctButNotOrdered() {
    Spliterator<String> split = Set.of("A", "B").spliterator();
    assertThat(split.hasCharacteristics(Spliterator.DISTINCT)).isTrue();
    // HashSet is NOT guaranteed ORDERED
}

@Test void treeSetIsSortedAndDistinct() {
    Spliterator<String> split = new TreeSet<>(List.of("C", "A", "B")).spliterator();
    assertThat(split.hasCharacteristics(Spliterator.SORTED)).isTrue();
    assertThat(split.hasCharacteristics(Spliterator.DISTINCT)).isTrue();
    assertThat(split.hasCharacteristics(Spliterator.ORDERED)).isTrue();
}

@Test void sizedEnablesExactSizeEstimate() {
    Spliterator<String> split = List.of("A", "B", "C").spliterator();
    assertThat(split.estimateSize()).isEqualTo(3);  // exact because SIZED
}
