// File: src/test/java/com/bank/java8/SpliteratorTest.java
package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.Spliterator;
import static org.assertj.core.api.Assertions.assertThat;

class SpliteratorTest {

    @Test
    void arrayListSpliteratorIsSizedAndOrdered() {
        List<Integer> arrayList = List.of(10, 20, 30);
        Spliterator<Integer> sp = arrayList.spliterator();

        assertThat(sp.hasCharacteristics(Spliterator.SIZED)).isTrue();
        assertThat(sp.hasCharacteristics(Spliterator.ORDERED)).isTrue();
        assertThat(sp.estimateSize()).isEqualTo(3);   // exact count known (SIZED)
    }
}
